const item = $input.first().json;
const body = item.body || item;

function firstNonEmpty(...values) {
  for (const value of values) {
    if (typeof value === 'string' && value.trim()) return value.trim();
  }
  return '';
}

function normalizeMode(value) {
  const text = String(value || '').trim().toLowerCase();
  if (['user_page', 'userpage', 'homepage', 'home_page'].includes(text)) return 'user_page';
  if (text === 'batch') return 'batch';
  if (text === 'single') return 'single';
  return '';
}

function normalizePositiveInt(value) {
  if (value === undefined || value === null || value === '') return null;
  const n = Number.parseInt(String(value).trim(), 10);
  return Number.isFinite(n) && n > 0 ? n : null;
}

function looksLikeHomepageShare(text) {
  const raw = String(text || '');
  return (
    /查看TA的更多作品/.test(raw) ||
    /更多作品/.test(raw) ||
    /douyin\.com\/user\/[A-Za-z0-9_\-]+/.test(raw) ||
    /iesdouyin\.com\/share\/user\/\d+/.test(raw)
  );
}

const modeOverride = normalizeMode(
  body.mode ?? body.download_mode ?? body.modeOverride ?? ''
);
const maxVideos = normalizePositiveInt(
  body.max_videos ?? body.maxVideos ?? body.limit
);

const rawSingle = firstNonEmpty(
  body.input,
  body.share_text,
  body.text,
  body.url
);

let urlList;
if (Array.isArray(body.urls) && body.urls.length > 0) {
  urlList = body.urls.map(v => String(v || '').trim()).filter(Boolean);
} else if (rawSingle) {
  urlList = [rawSingle];
} else {
  throw new Error('Must provide url / urls / input / share_text / text');
}

const count = urlList.length;
let mode;
if (modeOverride) {
  mode = modeOverride;
} else if (count > 1) {
  mode = 'batch';
} else if (looksLikeHomepageShare(urlList[0])) {
  mode = 'user_page';
} else {
  mode = 'single';
}

return [{
  json: {
    mode,
    urls: urlList,
    count,
    raw_input: rawSingle || urlList.join('\n'),
    max_videos: maxVideos
  }
}];

const r = $input.first().json;
return [{
  json: {
    mode: 'single',
    ok: r.ok,
    saved_path: r.saved_path || null,
    wav_path: r.wav_path || null,
    meta: r.meta || { title: null, cover_path: null },
    error: r.error || null,
    detail: r.detail || null
  }
}];

const r = $input.first().json;
return [{
  json: {
    mode: 'batch',
    ok: r.ok,
    job_id: r.job_id,
    total: r.total
  }
}];

const r = $input.first().json;
return [{
  json: {
    mode: 'user_page',
    ok: r.ok,
    job_id: r.job_id || null,
    total: r.total ?? 0,
    discovered_total: r.discovered_total ?? null,
    skipped_existing: r.skipped_existing ?? null,
    user_page: r.user_page || null,
    output_dir: r.output_dir || null,
    error: r.error || null,
    detail: r.detail || null
  }
}];

const item = $input.first().json;
const body = item.body || item;
const query = item.query || {};
const params = item.params || {};
const job_id = body.job_id || body.jobId || query.job_id || query.jobId || params.job_id || params.jobId;

if (!job_id) {
  throw new Error('Must provide job_id');
}

return [{ json: { job_id } }];

const r = $input.first().json;
const job_id = $('规范化输入').first().json.job_id;
return [{
  json: {
    mode: 'batch_status',
    job_id,
    ok: r.ok,
    status: r.status || null,
    total: r.total ?? null,
    done: r.done ?? null,
    failed: r.failed ?? null,
    files: Array.isArray(r.files) ? r.files : [],
    audio_files: Array.isArray(r.audio_files) ? r.audio_files : [],
    errors: Array.isArray(r.errors) ? r.errors : [],
    error: r.error || null
  }
}];

// Run Once for All Items
const root = $input.first().json;
const apiKey = root.api_key || root.body?.api_key || $vars.API_KEY || '';
const docName = root.doc_name || root.body?.doc_name || 'DKX作者分析';
const items = root.items || root.body?.items || [];
if (!apiKey) throw new Error('api_key 为空：请在请求体传入 api_key，或配置 $vars.API_KEY');
if (!Array.isArray(items) || items.length === 0) throw new Error('items 为空：请传入字幕 json 数组 items[]');
return [{ json: { api_key: apiKey, doc_name: docName, items } }];

// Run Once for All Items
const root = $input.first().json;
const items = Array.isArray(root.items) ? root.items : [];
if (items.length === 0) throw new Error('没有可展开的字幕 item');
return items.map((item, index) => ({
  json: { index: index + 1, api_key: root.api_key || '', doc_name: root.doc_name || 'DKX作者分析', ...item }
}));

const root = $json;
const sourceFile = root.source_file || root.file?.split('/').pop() || `video_${root.index || ''}.json`;
const baseName = sourceFile.replace(/\.(json|srt|txt)$/i, '');
let title = baseName.replace(/^\d+\([^)]*\)/, '');
title = title.replace(/\d{1,2}\.\d{1,2}\.\d{1,2}:\d{2}$/, '').trim();
if (!title) title = baseName;
return [{ json: { ...root, source_file: sourceFile, title, raw_title: title } }];

const root = $json;
const segments = Array.isArray(root.segments) ? root.segments : [];
const transcript = segments
  .map(seg => (seg?.text || '').trim())
  .filter(Boolean)
  .join('\n')
  .replace(/\[\d+\]/g, '')
  .replace(/[ \t]+\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();
return [{ json: { ...root, transcript, answer: transcript } }];

// Run Once for All Items
return $input.all().map(item => {
  const root = item.json;
  const transcript = root.transcript || root.answer || '';
  return {
    json: {
      index: root.index,
      source_file: root.source_file || '',
      title: root.title || root.raw_title || `视频${root.index || ''}`,
      raw_title: root.raw_title || root.title || '',
      api_key: root.api_key || '',
      doc_name: root.doc_name || 'DKX作者分析',
      answer: transcript,
      transcript,
      asr_status: transcript ? 'success' : 'error',
      asr_error: transcript ? '' : 'transcript empty',
      asr_success: Boolean(transcript && transcript.trim().length > 0)
    }
  };
});

const allItems = $input.all();
if (allItems.length === 0) throw new Error('上游没有输出任何 item，请检查节点4是否正常执行');
const inputData = [];
for (const item of allItems) {
  const data = item.json;
  const answer = data.answer || data.transcript || '';
  if (!data.asr_success || !answer) continue;
  inputData.push({ answer, errorBody: null, error_message: data.asr_error || '' });
}
if (inputData.length === 0) throw new Error('所有视频 ASR 转写均为空或失败，无法生成原始文案文档');
const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const sanitize = (s) => String(s || 'untitled').replace(/[\\/:*?"<>|]/g, '_').replace(/\\s+/g, ' ').trim().slice(0, 80) || 'untitled';
const ts = `${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}_${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;
const rawDocName = String(allItems[0].json?.doc_name || '纯文案版');
const safeDocName = sanitize(rawDocName);
const fileName = `${ts}_pure.txt`;
const savePath = `/opt/douyin-fetcher/d905_outputs/${safeDocName}/${fileName}`;
const lines = ['文档类型：原始文案', `作者：${rawDocName}`, `生成时间：${now.toISOString()}`, ''];
for (const [idx, item] of inputData.entries()) {
  const text = String(item?.answer || '').trim();
  if (!text) continue;
  lines.push(`## 第${idx + 1}条`);
  lines.push(text);
  lines.push('');
}
return [{
  json: {
    api_key: allItems[0].json?.api_key || '',
    doc_name: rawDocName,
    input_data: inputData,
    success_count: inputData.length,
    doc_type: 'pure',
    file_name: fileName,
    save_path: savePath,
    file_text: lines.join('\\n')
  }
}];

const allItems = $input.all();
if (allItems.length === 0) throw new Error('上游没有输出任何 item，请检查节点4是否正常执行');
const textList = [];
const failed = [];
const SEPARATOR = '\n\n---\n\n';
for (const item of allItems) {
  const data = item.json;
  const answer = data.answer || data.transcript || '';
  const title = data.title || data.raw_title || `视频${data.index || ''}`;
  if (!data.asr_success || !answer || answer.trim().length < 10) {
    failed.push({ source_file: data.source_file || '', reason: data.asr_error || '文案为空或过短' });
    continue;
  }
  textList.push({ title, answer, source_file: data.source_file || '' });
}
if (textList.length === 0) throw new Error('所有视频文案过滤后为空，无法进行LLM提炼');
const combineTextList = [];
let current = '';
for (const { title, answer } of textList) {
  let single = `${title}；${answer}`;
  if (single.length > 2000) single = single.slice(0, 2000);
  const appendLen = current ? SEPARATOR.length + single.length : single.length;
  if (current.length + appendLen <= 1000) {
    current = current ? current + SEPARATOR + single : single;
  } else {
    if (current) combineTextList.push(current);
    current = single;
  }
}
if (current) combineTextList.push(current);
const filtered = combineTextList.filter(t => t.trim());
if (filtered.length === 0) throw new Error('分段后文本列表为空，请检查文案内容');
return filtered.map((text, idx) => ({
  json: {
    combine_text: text,
    segment_index: idx + 1,
    segment_total: filtered.length,
    api_key: allItems[0].json?.api_key || '',
    doc_name: allItems[0].json?.doc_name || '',
    failed_count: failed.length,
    success_count: textList.length
  }
}));

function safeJsonParse(value) {
  if (!value) return {};
  if (typeof value === 'object') return value;
  try { return JSON.parse(value); }
  catch (e) { return { parse_error: `JSON解析失败: ${e.message}`, raw_text: String(value).slice(0, 200) }; }
}
return $input.all().map(item => {
  const root = item.json;
  const raw = safeJsonParse(root.llm_raw);
  const answer = raw.copywriting || raw.answer || raw.content || raw.data?.copywriting || '';
  const errorMessage = raw.parse_error || raw.error_message || raw.message || raw.error || '';
  const hookAnswer = answer ? (typeof answer === 'string' ? answer : JSON.stringify(answer)) : '';
  return { json: { ...root, hook_answer: hookAnswer, llm_error: errorMessage, points_consumed: raw.points_consumed ?? null, hook_success: Boolean(hookAnswer && hookAnswer.trim()) } };
});

const allItems = $input.all();
if (allItems.length === 0) throw new Error('上游没有输出任何 item，请检查节点8提炼钩子是否正常执行');
const inputData = [];
const failed = [];
for (const item of allItems) {
  const data = item.json;
  const answer = data.hook_answer || '';
  if (!data.hook_success || !answer || answer.trim() === '') {
    failed.push({ segment_index: data.segment_index, reason: data.llm_error || '钩子结果为空或LLM失败' });
    continue;
  }
  inputData.push({ answer, errorBody: null, error_message: data.llm_error || '' });
}
if (inputData.length === 0) throw new Error(`所有分段钩子提炼均失败（共 ${failed.length} 段），请检查节点8输出`);
const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const sanitize = (s) => String(s || 'untitled').replace(/[\\/:*?"<>|]/g, '_').replace(/\\s+/g, ' ').trim().slice(0, 80) || 'untitled';
const ts = `${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}_${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;
const rawDocName = String(allItems[0].json?.doc_name || '钩子提炼版');
const safeDocName = sanitize(rawDocName);
const fileName = `${ts}_hook.txt`;
const savePath = `/opt/douyin-fetcher/d905_outputs/${safeDocName}/${fileName}`;
const lines = ['文档类型：钩子提炼', `作者：${rawDocName}`, `生成时间：${now.toISOString()}`, ''];
for (const [idx, item] of inputData.entries()) {
  const text = String(item?.answer || '').trim();
  if (!text) continue;
  lines.push(`## 第${idx + 1}条`);
  lines.push(text);
  lines.push('');
}
return [{
  json: {
    api_key: allItems[0].json?.api_key || '',
    doc_name: rawDocName,
    input_data: inputData,
    failed,
    success_count: inputData.length,
    failed_count: failed.length,
    doc_type: 'hook',
    file_name: fileName,
    save_path: savePath,
    file_text: lines.join('\\n')
  }
}];

function safeJsonParse(value) {
  if (!value) return {};
  if (typeof value === 'object') return value;
  try { return JSON.parse(value); }
  catch (e) { return { parse_error: `JSON解析失败: ${e.message}`, raw_text: String(value).slice(0, 200) }; }
}
return $input.all().map(item => {
  const root = item.json;
  const raw = safeJsonParse(root.llm_raw_keyword);
  const answer = raw.copywriting || raw.answer || raw.content || raw.data?.copywriting || '';
  const errorMessage = raw.parse_error || raw.error_message || raw.message || raw.error || '';
  const keywordAnswer = answer ? (typeof answer === 'string' ? answer : JSON.stringify(answer)) : '';
  return { json: { ...root, keyword_answer: keywordAnswer, llm_error: errorMessage, points_consumed: raw.points_consumed ?? null, keyword_success: Boolean(keywordAnswer && keywordAnswer.trim()) } };
});

const allItems = $input.all();
if (allItems.length === 0) throw new Error('上游没有输出任何 item，请检查节点11提炼核心词是否正常执行');
const inputData = [];
const failed = [];
for (const item of allItems) {
  const data = item.json;
  const answer = data.keyword_answer || '';
  if (!data.keyword_success || !answer || answer.trim() === '') {
    failed.push({ segment_index: data.segment_index, reason: data.llm_error || '核心词结果为空或LLM失败' });
    continue;
  }
  inputData.push({ answer, errorBody: null, error_message: data.llm_error || '' });
}
if (inputData.length === 0) throw new Error(`所有分段核心词提炼均失败（共 ${failed.length} 段），请检查节点11输出`);
const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const sanitize = (s) => String(s || 'untitled').replace(/[\\/:*?"<>|]/g, '_').replace(/\\s+/g, ' ').trim().slice(0, 80) || 'untitled';
const ts = `${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}_${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;
const rawDocName = String(allItems[0].json?.doc_name || '核心词版');
const safeDocName = sanitize(rawDocName);
const fileName = `${ts}_keyword.txt`;
const savePath = `/opt/douyin-fetcher/d905_outputs/${safeDocName}/${fileName}`;
const lines = ['文档类型：核心词', `作者：${rawDocName}`, `生成时间：${now.toISOString()}`, ''];
for (const [idx, item] of inputData.entries()) {
  const text = String(item?.answer || '').trim();
  if (!text) continue;
  lines.push(`## 第${idx + 1}条`);
  lines.push(text);
  lines.push('');
}
return [{
  json: {
    api_key: allItems[0].json?.api_key || '',
    doc_name: rawDocName,
    input_data: inputData,
    failed,
    success_count: inputData.length,
    failed_count: failed.length,
    doc_type: 'keyword',
    file_name: fileName,
    save_path: savePath,
    file_text: lines.join('\\n')
  }
}];

const result = { text_combine: '', text_title_combine: '', core_keyword: '', error_summary: [] };
for (const item of $input.all()) {
  const { doc_type, file_url, save_path, doc_error, doc_success, doc_status } = item.json;
  const finalPath = file_url || save_path || '';
  if (doc_type === 'pure') result.text_combine = finalPath;
  if (doc_type === 'hook') result.text_title_combine = finalPath;
  if (doc_type === 'keyword') result.core_keyword = finalPath;
  if (!finalPath || doc_success === false) {
    result.error_summary.push({ doc_type: doc_type || 'unknown', status: doc_status || 'error', error: doc_error || '文件路径为空' });
  }
}
const errorText = result.error_summary.length
  ? ['------------------------', '失败摘要：', ...result.error_summary.map(e => `${e.doc_type}: ${e.error}`)].join('\n')
  : '';
const reply = [
  '后半套已执行完成，服务器本地文件路径如下：',
  '------------------------',
  '原始文案：',
  result.text_combine || '（生成失败）',
  '------------------------',
  '钩子提炼：',
  result.text_title_combine || '（生成失败）',
  '------------------------',
  '核心词：',
  result.core_keyword || '（生成失败）',
  errorText
].filter(Boolean).join('\n');
return [{ json: { ...result, reply, error_summary: result.error_summary } }];

const item = $input.first().json;
const body = item.body || item;
const query = item.query || {};
const params = item.params || {};

function parseBoolean(value, fallback) {
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value === 'boolean') return value;
  const text = String(value).trim().toLowerCase();
  if (['1', 'true', 'yes', 'on'].includes(text)) return true;
  if (['0', 'false', 'no', 'off'].includes(text)) return false;
  return fallback;
}

function toUserPageArray(value) {
  if (Array.isArray(value)) {
    return value.map(v => String(v || '').trim()).filter(Boolean);
  }
  if (typeof value === 'string' && value.trim()) {
    return value
      .split(/\r?\n|,/)
      .map(v => v.trim())
      .filter(Boolean);
  }
  return [];
}

function pickFirst(...values) {
  for (const value of values) {
    if (typeof value === 'string' && value.trim()) return value.trim();
  }
  return '';
}

const prefer_low_bitrate = parseBoolean(
  body.prefer_low_bitrate ?? body.preferLowBitrate ?? query.prefer_low_bitrate ?? query.preferLowBitrate,
  false
);

const user_pages = toUserPageArray(
  body.user_pages ?? body.userPages ?? query.user_pages ?? query.userPages ?? params.user_pages
);

const author_keys = toUserPageArray(
  body.author_keys ??
  body.authorKeys ??
  body.authors ??
  body.author ??
  body.input ??
  body.text ??
  query.author_keys ??
  query.authorKeys ??
  query.authors ??
  query.author ??
  query.input ??
  query.text ??
  params.author_keys ??
  params.authors ??
  params.author ??
  params.input
);

return [{
  json: {
    entry: 'check_updates',
    prefer_low_bitrate,
    user_pages,
    author_keys,
    raw_input: pickFirst(body.input, body.text, body.author, query.input, query.text, query.author)
  }
}];

